  methods: {
    // ==================== 距离计算辅助方法 ====================
    distanceToSegment(px, py, x1, y1, x2, y2) {
      const dx = x2 - x1;
      const dy = y2 - y1;
      const lenSq = dx * dx + dy * dy;
      if (lenSq === 0) {
        return Math.sqrt((px - x1) ** 2 + (py - y1) ** 2);
      }
      let t = ((px - x1) * dx + (py - y1) * dy) / lenSq;
      t = Math.max(0, Math.min(1, t));
      const nearX = x1 + t * dx;
      const nearY = y1 + t * dy;
      return Math.sqrt((px - nearX) ** 2 + (py - nearY) ** 2);
    },

    // ==================== 检测点是否在多边形内 ====================
    isPointInPolygon(px, py, polygon) {
      let inside = false;
      for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
        const xi = polygon[i].x, yi = polygon[i].y;
        const xj = polygon[j].x, yj = polygon[j].y;
        const intersect = ((yi > py) !== (yj > py)) &&
          (px < (xj - xi) * (py - yi) / (yj - yi) + xi);
        if (intersect) inside = !inside;
      }
      return inside;
    },

    // ==================== 更新折线数据到 form ====================
    updateCrossLineData() {
      if (this.polylinePoints.length >= 2) {
        const points = this.polylinePoints.map(p => ({
          x: Number((p.x * this.timesX).toFixed(0)),
          y: Number((p.y * this.timesY).toFixed(0))
        }));
        this.ruleForm.cross_line = {
          points: points,
          direction: this.lineDirection,
          p1: points[0],
          p2: points[points.length - 1]
        };
        console.log('保存折线数据:', this.ruleForm.cross_line);
      } else {
        this.ruleForm.cross_line = {};
      }
    },

    // ==================== 从框更新折线数据 ====================
    updateCrossLineDataFromBox(polygon) {
      if (!polygon || polygon.length < 2) return;
      const points = polygon.map(p => ({
        x: Number((p.x * this.timesX).toFixed(0)),
        y: Number((p.y * this.timesY).toFixed(0))
      }));
      const first = points[0];
      const last = points[points.length - 1];
      let finalPoints = points;
      if (points.length > 2 && first.x === last.x && first.y === last.y) {
        finalPoints = points.slice(0, -1);
      }
      this.ruleForm.cross_line = {
        points: finalPoints,
        direction: this.lineDirection,
        p1: finalPoints[0],
        p2: finalPoints[finalPoints.length - 1]
      };
      console.log('从框更新折线数据:', this.ruleForm.cross_line);
    },

    // ==================== 处理Canvas点击切换方向（框模式） ====================
    handleCanvasClickForDirection(e) {
      const cav = this.$refs.mycanvas;
      if (!cav) return;
      if (this.drawLineOpen || this.mark_list.length === 0) return;
      
      const rect = cav.getBoundingClientRect();
      const scaleX = cav.width / rect.width;
      const scaleY = cav.height / rect.height;
      const x = (e.clientX - rect.left) * scaleX;
      const y = (e.clientY - rect.top) * scaleY;
      
      for (let i = 0; i < this.mark_list.length; i++) {
        const polygon = this.mark_list[i];
        if (polygon.length < 3) continue;
        if (this.isPointInPolygon(x, y, polygon)) {
          this.lineDirection = this.lineDirection === 'left' ? 'right' : 'left';
          console.log('框内点击切换方向:', this.lineDirection);
          this.updateCrossLineDataFromBox(polygon);
          this.initCanvas();
          this.$message.success(`方向已切换为: ${this.lineDirection === 'left' ? 'IN左 OUT右' : 'IN右 OUT左'}`);
          return;
        }
      }
    },

