    // ==================== 表格内绘制（支持折线多点和方向） ====================
    tableCanvasForTable(id, list, crossLineData, type, resolution) {
      var parts = resolution.split('x');
      var WW = parseInt(parts[0], 10);
      var HH = parseInt(parts[1], 10);
      
      this.$nextTick(() => {
        let cav = this.$refs[`tableCanvas_${id}`];
        if (!cav) return;
        
        cav.width = "96";
        cav.height = "54";
        let ctx = cav.getContext("2d");
        
        let XX = WW / 96;
        let YY = HH / 54;
        
        ctx.clearRect(0, 0, 96, 54);
        
        if (list && list.length > 0) {
          for (let w = 0; w < list.length; w++) {
            if (list[w].length < 3) continue;
            ctx.beginPath();
            ctx.strokeStyle = list[w][0].color || '#f00';
            ctx.lineWidth = 1;
            ctx.moveTo(list[w][0].x / XX, list[w][0].y / YY);
            for (let i = 1; i < list[w].length; i++) {
              ctx.lineTo(list[w][i].x / XX, list[w][i].y / YY);
            }
            ctx.closePath();
            ctx.stroke();
          }
        }
        
        if (crossLineData) {
          try {
            if (crossLineData.points && Array.isArray(crossLineData.points) && crossLineData.points.length >= 2) {
              const points = crossLineData.points.map(p => ({
                x: Math.min(96, Math.max(0, Number(p.x) / XX)),
                y: Math.min(54, Math.max(0, Number(p.y) / YY))
              }));
              ctx.beginPath();
              ctx.moveTo(points[0].x, points[0].y);
              for (let i = 1; i < points.length; i++) {
                ctx.lineTo(points[i].x, points[i].y);
              }
              ctx.strokeStyle = "#ffd700";
              ctx.lineWidth = 1.5;
              ctx.stroke();
              points.forEach((p) => {
                ctx.beginPath();
                ctx.arc(p.x, p.y, 2, 0, 2 * Math.PI);
                ctx.fillStyle = '#ffd700';
                ctx.fill();
              });
              if (points.length >= 2) {
                const direction = crossLineData.direction || 'right';
                const midIndex = Math.floor(points.length / 2);
                const pA = points[midIndex - 1] || points[0];
                const pB = points[midIndex] || points[points.length - 1];
                const mx = (pA.x + pB.x) / 2;
                const my = (pA.y + pB.y) / 2;
                if (direction === 'left') {
                  ctx.beginPath(); ctx.fillStyle = '#44ff44'; ctx.arc(mx - 6, my, 2, 0, 2 * Math.PI); ctx.fill();
                  ctx.beginPath(); ctx.fillStyle = '#ff4444'; ctx.arc(mx + 6, my, 2, 0, 2 * Math.PI); ctx.fill();
                } else {
                  ctx.beginPath(); ctx.fillStyle = '#ff4444'; ctx.arc(mx - 6, my, 2, 0, 2 * Math.PI); ctx.fill();
                  ctx.beginPath(); ctx.fillStyle = '#44ff44'; ctx.arc(mx + 6, my, 2, 0, 2 * Math.PI); ctx.fill();
                }
              }
            } else if (crossLineData.p1 && crossLineData.p2) {
              const p1 = {
                x: Math.min(96, Math.max(0, Number(crossLineData.p1.x) / XX)),
                y: Math.min(54, Math.max(0, Number(crossLineData.p1.y) / YY))
              };
              const p2 = {
                x: Math.min(96, Math.max(0, Number(crossLineData.p2.x) / XX)),
                y: Math.min(54, Math.max(0, Number(crossLineData.p2.y) / YY))
              };
              ctx.beginPath();
              ctx.moveTo(p1.x, p1.y);
              ctx.lineTo(p2.x, p2.y);
              ctx.strokeStyle = "#ffd700";
              ctx.lineWidth = 1.5;
              ctx.stroke();
              const direction = crossLineData.direction || 'right';
              const mx = (p1.x + p2.x) / 2;
              const my = (p1.y + p2.y) / 2;
              if (direction === 'left') {
                ctx.beginPath(); ctx.fillStyle = '#44ff44'; ctx.arc(mx - 6, my, 2, 0, 2 * Math.PI); ctx.fill();
                ctx.beginPath(); ctx.fillStyle = '#ff4444'; ctx.arc(mx + 6, my, 2, 0, 2 * Math.PI); ctx.fill();
              } else {
                ctx.beginPath(); ctx.fillStyle = '#ff4444'; ctx.arc(mx - 6, my, 2, 0, 2 * Math.PI); ctx.fill();
                ctx.beginPath(); ctx.fillStyle = '#44ff44'; ctx.arc(mx + 6, my, 2, 0, 2 * Math.PI); ctx.fill();
              }
            }
          } catch(e) {
            console.error('绘制折线失败:', e);
          }
        }
      });
    },

