    // ==================== 修改 tableCanvasMax（支持折线多点和方向） ====================
    tableCanvasMax(id, list, crossLineData, type, resolution) {
      var parts = resolution.split('x');
      var WW = parseInt(parts[0], 10);
      var HH = parseInt(parts[1], 10);
      
      this.$nextTick(() => {
        let cav = this.$refs[`tableCanvas_tableMax`];
        if (!cav) return;
        
        cav.width = "800";
        cav.height = "400";
        let ctx = cav.getContext("2d");
        
        let XX = WW / 800;
        let YY = HH / 400;
        
        ctx.clearRect(0, 0, 800, 400);
        
        if (list && list.length > 0) {
          for (let w = 0; w < list.length; w++) {
            if (list[w].length < 3) continue;
            ctx.beginPath();
            ctx.strokeStyle = list[w][0].color || '#f00';
            ctx.lineWidth = 2;
            ctx.moveTo(list[w][0].x / XX, list[w][0].y / YY);
            for (let i = 1; i < list[w].length; i++) {
              ctx.lineTo(list[w][i].x / XX, list[w][i].y / YY);
            }
            ctx.closePath();
            ctx.stroke();
          }
        }
        
        if (crossLineData) {
          try {
            if (crossLineData.points && Array.isArray(crossLineData.points) && crossLineData.points.length >= 2) {
              const points = crossLineData.points.map(p => ({
                x: Math.min(800, Math.max(0, Number(p.x) / XX)),
                y: Math.min(400, Math.max(0, Number(p.y) / YY))
              }));
              ctx.beginPath();
              ctx.moveTo(points[0].x, points[0].y);
              for (let i = 1; i < points.length; i++) {
                ctx.lineTo(points[i].x, points[i].y);
              }
              ctx.strokeStyle = "#ffd700";
              ctx.lineWidth = 2;
              ctx.stroke();
              points.forEach((p) => {
                ctx.beginPath();
                ctx.arc(p.x, p.y, 4, 0, 2 * Math.PI);
                ctx.fillStyle = '#ffd700';
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 1;
                ctx.stroke();
              });
              if (points.length >= 2) {
                this.drawArrowsOnPolylineMax(ctx, points, crossLineData.direction || 'right');
              }
            } else if (crossLineData.p1 && crossLineData.p2) {
              const p1 = {
                x: Math.min(800, Math.max(0, Number(crossLineData.p1.x) / XX)),
                y: Math.min(400, Math.max(0, Number(crossLineData.p1.y) / YY))
              };
              const p2 = {
                x: Math.min(800, Math.max(0, Number(crossLineData.p2.x) / XX)),
                y: Math.min(400, Math.max(0, Number(crossLineData.p2.y) / YY))
              };
              ctx.beginPath();
              ctx.moveTo(p1.x, p1.y);
              ctx.lineTo(p2.x, p2.y);
              ctx.strokeStyle = "#ffd700";
              ctx.lineWidth = 2;
              ctx.stroke();
              this.drawArrowsOnSegmentMax(ctx, p1, p2, crossLineData.direction || 'right');
            }
          } catch(e) {
            console.error('绘制折线失败:', e);
          }
        }
      });
    },

    // ==================== 在折线上绘制箭头（弹窗大图） ====================
    drawArrowsOnPolylineMax(ctx, points, direction) {
      if (points.length < 2) return;
      
      let totalLen = 0;
      let segmentLengths = [];
      for (let i = 1; i < points.length; i++) {
        const dx = points[i].x - points[i-1].x;
        const dy = points[i].y - points[i-1].y;
        const len = Math.sqrt(dx * dx + dy * dy);
        segmentLengths.push(len);
        totalLen += len;
      }
      
      let halfLen = totalLen / 2;
      let accumulated = 0;
      let midIndex = 0;
      let midT = 0;
      for (let i = 0; i < segmentLengths.length; i++) {
        if (accumulated + segmentLengths[i] >= halfLen) {
          midIndex = i;
          midT = (halfLen - accumulated) / segmentLengths[i];
          break;
        }
        accumulated += segmentLengths[i];
      }
      
      midIndex = Math.min(midIndex, points.length - 2);
      const pA = points[midIndex];
      const pB = points[midIndex + 1];
      const mx = pA.x + (pB.x - pA.x) * midT;
      const my = pA.y + (pB.y - pA.y) * midT;
      
      const segDx = pB.x - pA.x;
      const segDy = pB.y - pA.y;
      const segLen = Math.sqrt(segDx * segDx + segDy * segDy);
      if (segLen === 0) return;
      const segUx = segDx / segLen;
      const segUy = segDy / segLen;
      
      const arrowLen = 70;
      let leftX = mx - segUy * arrowLen;
      let leftY = my + segUx * arrowLen;
      let rightX = mx + segUy * arrowLen;
      let rightY = my - segUx * arrowLen;
      
      leftX = Math.min(780, Math.max(20, leftX));
      leftY = Math.min(380, Math.max(20, leftY));
      rightX = Math.min(780, Math.max(20, rightX));
      rightY = Math.min(380, Math.max(20, rightY));
      
      let leftText, rightText, leftColor, rightColor;
      if (direction === 'left') {
        leftText = 'IN'; leftColor = '#44ff44';
        rightText = 'OUT'; rightColor = '#ff4444';
      } else {
        leftText = 'OUT'; leftColor = '#ff4444';
        rightText = 'IN'; rightColor = '#44ff44';
      }
      
      const drawArrow = (fromX, fromY, toX, toY, color) => {
        ctx.strokeStyle = color;
        ctx.fillStyle = color;
        ctx.lineWidth = 2;
        const headLen = 10;
        const angle = Math.atan2(toY - fromY, toX - fromX);
        ctx.beginPath();
        ctx.moveTo(fromX, fromY);
        ctx.lineTo(toX, toY);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(toX, toY);
        let x1 = toX - headLen * Math.cos(angle - Math.PI / 6);
        let y1 = toY - headLen * Math.sin(angle - Math.PI / 6);
        ctx.lineTo(x1, y1);
        ctx.moveTo(toX, toY);
        let x2 = toX - headLen * Math.cos(angle + Math.PI / 6);
        let y2 = toY - headLen * Math.sin(angle + Math.PI / 6);
        ctx.lineTo(x2, y2);
        ctx.stroke();
      };
      
      const drawText = (x, y, text, color) => {
        ctx.font = "bold 18px Arial";
        ctx.textAlign = "center";
        ctx.fillStyle = color;
        ctx.fillText(text, x, y - 12);
      };
      
      drawArrow(mx, my, leftX, leftY, leftColor);
      drawArrow(mx, my, rightX, rightY, rightColor);
      drawText(leftX, leftY, leftText, leftColor);
      drawText(rightX, rightY, rightText, rightColor);
    },

    // ==================== 在单条线段上绘制箭头（弹窗大图，兼容旧数据） ====================
    drawArrowsOnSegmentMax(ctx, p1, p2, direction) {
      const dx = p2.x - p1.x;
      const dy = p2.y - p1.y;
      const len = Math.sqrt(dx * dx + dy * dy);
      if (len === 0) return;
      
      const ux = dx / len;
      const uy = dy / len;
      const arrowLen = 70;
      const mx = (p1.x + p2.x) / 2;
      const my = (p1.y + p2.y) / 2;
      
      let leftX = mx - uy * arrowLen;
      let leftY = my + ux * arrowLen;
      let rightX = mx + uy * arrowLen;
      let rightY = my - ux * arrowLen;
      
      leftX = Math.min(780, Math.max(20, leftX));
      leftY = Math.min(380, Math.max(20, leftY));
      rightX = Math.min(780, Math.max(20, rightX));
      rightY = Math.min(380, Math.max(20, rightY));
      
      let leftText, rightText, leftColor, rightColor;
      if (direction === 'left') {
        leftText = 'IN'; leftColor = '#44ff44';
        rightText = 'OUT'; rightColor = '#ff4444';
      } else {
        leftText = 'OUT'; leftColor = '#ff4444';
        rightText = 'IN'; rightColor = '#44ff44';
      }
      
      const drawArrow = (fromX, fromY, toX, toY, color) => {
        ctx.strokeStyle = color;
        ctx.fillStyle = color;
        ctx.lineWidth = 2;
        const headLen = 10;
        const angle = Math.atan2(toY - fromY, toX - fromX);
        ctx.beginPath();
        ctx.moveTo(fromX, fromY);
        ctx.lineTo(toX, toY);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(toX, toY);
        let x1 = toX - headLen * Math.cos(angle - Math.PI / 6);
        let y1 = toY - headLen * Math.sin(angle - Math.PI / 6);
        ctx.lineTo(x1, y1);
        ctx.moveTo(toX, toY);
        let x2 = toX - headLen * Math.cos(angle + Math.PI / 6);
        let y2 = toY - headLen * Math.sin(angle + Math.PI / 6);
        ctx.lineTo(x2, y2);
        ctx.stroke();
      };
      
      const drawText = (x, y, text, color) => {
        ctx.font = "bold 18px Arial";
        ctx.textAlign = "center";
        ctx.fillStyle = color;
        ctx.fillText(text, x, y - 12);
      };
      
      drawArrow(mx, my, leftX, leftY, leftColor);
      drawArrow(mx, my, rightX, rightY, rightColor);
      drawText(leftX, leftY, leftText, leftColor);
      drawText(rightX, rightY, rightText, rightColor);
    },

    // ==================== 修改 handleData ====================
    handleData() {
      if (this.mark_list.length != 0 && !this.drawLineOpen) {
        let data = this.mark_list;
        let arr = [];
        for (let i = 0; i < data.length; i++) {
          arr.push(
            this.mark_list[i].map(v => ({
              x: (v.x * this.timesX).toFixed(0),
              y: (v.y * this.timesY).toFixed(0),
              type: v.type,
              color: v.color,
            }))
          );
        }
        this.mark_lists = arr;
      } else {
        this.mark_lists = [];
      }
      
      if (this.mark_list2.length != 0) {
        let data2 = this.mark_list2[0];
        let arr2 = [];
        for (let i = 0; i < data2.length; i++) {
          let x = (data2[i].x * this.timesX).toFixed(0);
          let y = (data2[i].y * this.timesY).toFixed(0);
          arr2.push({ x, y });
        }
        this.mark_lists2 = [arr2];
      } else {
        this.mark_lists2 = [];
      }

      // 折线数据处理 - 保存所有点和方向
      if (this.polylinePoints.length >= 2) {
        const points = this.polylinePoints.map(p => ({
          x: Number((Math.min(Math.max(p.x, 0), 640) * this.timesX).toFixed(0)),
          y: Number((Math.min(Math.max(p.y, 0), 360) * this.timesY).toFixed(0))
        }));
        this.ruleForm.cross_line = {
          points: points,
          direction: this.lineDirection,
          p1: points[0],
          p2: points[points.length - 1]
        };
        console.log('保存时的折线数据:', JSON.stringify(this.ruleForm.cross_line));
      } else if (this.mark_list3.length != 0 && this.drawLineOpen) {
        let data = this.mark_list3;
        let arr3 = [];
        let arr_w = [];
        for (let w = 0; w < data.length; w++) {
          for (let i = 0; i < data[w].length; i++) {
            let x = (data[w][i].x * this.timesX).toFixed(0);
            let y = (data[w][i].y * this.timesY).toFixed(0);
            arr3.push({ x, y, type: '报警' });
          }
          arr_w.push(arr3);
          arr3 = [];
        }
        this.mark_lists3 = [...arr_w];
        this.mark_lists3.sort((a, b) => b[0].y - a[0].y);
        this.ruleForm.cross_line = {
          p1: this.mark_lists3[0]?.[0] || {},
          p2: this.mark_lists3[0]?.[1] || {},
          direction: this.lineDirection
        };
      } else {
        this.mark_lists3 = [];
        this.ruleForm.cross_line = {};
      }
    },

