    handleTimesData(resolution) {
      let w = 640, h = 360;
      var parts = resolution.split('x');
      var width = parts[0];
      var height = parts[1];
      this.timesX = (width / w).toFixed(2);
      this.timesY = (height / h).toFixed(2);
